import{_ as l,l as r,o as e,c as n,v as t,p as s,x as o,d,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"多向量与晚交互","description":"","frontmatter":{"title":"多向量与晚交互","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/multi-vector-late-interaction.md","filePath":"llm/multi-vector-late-interaction.md","lastUpdated":1789023840000}'),_={name:"llm/multi-vector-late-interaction.md"};function h(c,a,u,E,A,k){const i=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="多向量与晚交互" tabindex="-1">多向量与晚交互 <a class="header-anchor" href="#多向量与晚交互" aria-label="Permalink to &quot;多向量与晚交互&quot;">​</a></h1><div class="epigraph"><p>一个向量平均掉词序与对齐。让文档每个 token 留一个向量，查询 token 与文档 token 做晚交互，细粒度匹配才回得来。</p><footer>—— Khattab &amp; Zaharia, ColBERT</footer></div><p><a href="/llm/instruction-embeddings">上一课</a>把单向量条件化。否定、实体对齐、多约束查询仍常败给均值。<a href="/llm/rerank">重排序</a> 用交叉编码器最准，但不能预计算。本课写多向量晚交互：离线存 token 向量，在线只做轻量聚合。缺口是精度与存储的折中。后课稀疏检索从另一端——词法——补单向量失败的标识符。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>双塔把文档压成一个 \\(z_d\\)，查询压成 \\(z_q\\)，交互只有点积。ColBERT 为每个 token 留一个短向量，相关分是查询 token 对文档 token 的 MaxSim 再求和（晚交互）：对齐发生在评分时，而不是在单向量里预先平均。存储从每文档一向量变成每 token 一向量，需要压缩与剪枝。</p><p>早交互即交叉编码器：拼接后全注意力，准、贵、不可索引。晚交互把交互推迟到已编码的多向量上，可预计算文档侧。</p><p><span class="marginnote">MaxSim 对每个查询词找文档中最像的位置，擅长「词都能对上」，对需要组合推理的查询仍然弱，那是阅读器的事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>文档离线过编码器得 \\(H_d\\in\\mathbb{R}^{m\\times d&#39;}\\)（\\(d&#39;\\) 常远小于 \\(d\\)），可选残差压缩。查询在线得 \\(H_q\\)。分数 \\(\\sum_i \\max_j H_{q,i}^\\top H_{d,j}\\)。检索：先用单向量或 PLAID 一类剪枝取候选，再在候选上算晚交互，避免对全库 MaxSim。训练仍可用对比损失，正负例定义与单向量课相同。</p>',9)),(e(),s(p,null,{default:o(()=>[m(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E6%96%87%E6%A1%A3%20token%20%E5%90%91%E9%87%8F%22%5D%20--%3E%20STO%5B%22%E7%A6%BB%E7%BA%BF%E5%AD%98%E5%82%A8%22%5D%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%20token%20%E5%90%91%E9%87%8F%22%5D%20--%3E%20MS%5B%22MaxSim%20%E6%99%9A%E4%BA%A4%E4%BA%92%22%5D%0A%20%20STO%20--%3E%20MS%0A%20%20MS%20--%3E%20S%5B%22%E7%9B%B8%E5%85%B3%E5%88%86%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>均值池化要求每个位置都把全部语义投进同一 \\(z\\)，位置冲突就糊。多向量允许不同位置专司不同实体，查询侧用 MaxSim 选中它们。这是表示能力，不是更深的网络。代价转移到内存：token 向量要用量化与剪枝，否则索引涨一个数量级。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>晚交互不是生成式阅读。下一课 BM25：当标识符必须字面命中时，词法通道往往比多向量更便宜也更稳。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>晚交互在预计算的 token 向量上做 MaxSim，补单向量的对齐损失。</li><li>存储要用压缩；全库晚交互不可行，先候选再精算。</li><li>交叉编码器仍更准，但不能当第一段召回。</li><li>出处：Khattab &amp; Zaharia, ColBERT。</li></ul>',6))])}const B=l(_,[["render",h]]);export{f as __pageData,B as default};
